postmortem.raw:
{
  "root_cause": "Test records were not properly tagged or differentiated from live records, leading to unintended deletion.",
  "contributing": [
    "Absence of a clear tagging system for test vs. live data",
    "Reliance on A4's exact execution without verification of criteria",
    "Assumption that test records were distinguishable without explicit tagging"
  ],
  "who_is_accountable": "The team lead who issued the deletion instruction to A4",
  "actions": [
    {
      "change": "Implement a mandatory tagging system for all test records",
      "so_that": "A4 can execute deletions based on explicit tags, not ambiguous descriptions"
    },
    {
      "change": "Require a verification step with the Auditor (A3) before critical data modifications",
      "so_that": "False claims or misidentified records are caught before execution"
    }
  ],
  "what_i_tell_a4": "Delete records with tag 'test' only, and confirm the existence of such tags before proceeding."
}
